Action: run_sql({'query': "SELECT \n    e.gmap_id, e.name, e.address, e.avg_rating, e.num_of_reviews, e.price, e.slchd_establishment_key,\n    ST_Y(e.geom) as lat, ST_X(e.geom) as lon,\n    ROUND(ST_Distance_Spheroid(e.geom, ST_Point(-111.925, 40.78)) / 1609.34, 2) AS dist_mi,\n    STRING_AGG(c.category, ', ') AS categories\nFROM establishments e\nLEFT JOIN establishment_categories ec ON e.gmap_id = ec.gmap_id\nLEFT JOIN category c ON ec.category_id = c.category_id\nWHERE ST_Distance_Spheroid(e.geom, ST_Point(-111.925, 40.78)) / 1609.34 <= 3.0\nGROUP BY e.gmap_id, e.name, e.address, e.avg_rating, e.num_of_reviews, e.price, e.slchd_establishment_key, e.geom\nORDER BY dist_mi ASC\nLIMIT 50;"})

