Action: run_sql({'query': "SELECT \n    e.gmap_id, e.name, e.address, e.avg_rating, e.num_of_reviews, e.price, e.slchd_establishment_key,\n    ROUND(SQRT(POW((ST_Y(e.geom) - 40.78)*69, 2) + POW((ST_X(e.geom) - (-111.925))*52, 2)), 2) AS dist_mi,\n    COUNT(r.rating) as matching_reviews,\n    STRING_AGG(DISTINCT SUBSTRING(r.text, 1, 100), ' | ') as review_snippets\nFROM establishments e\nJOIN review r ON e.gmap_id = r.gmap_id\nWHERE (e.address LIKE '%84116%' OR e.address LIKE '%Rose Park%' OR SQRT(POW((ST_Y(e.geom) - 40.78)*69, 2) + POW((ST_X(e.geom) - (-111.925))*52, 2)) <= 2.0)\n  AND (LOWER(r.text) LIKE '%breakfast%' OR LOWER(r.text) LIKE '%burrito%' OR LOWER(r.text) LIKE '%huevos%' OR LOWER(r.text) LIKE '%chilaquiles%' OR LOWER(r.text) LIKE '%egg%' OR LOWER(r.text) LIKE '%savory%')\nGROUP BY e.gmap_id, e.name, e.address, e.avg_rating, e.num_of_reviews, e.price, e.slchd_establishment_key, e.geom\nORDER BY matching_reviews DESC, e.avg_rating DESC\nLIMIT 20;"})

